from pathlib import Path
r=Path('apps/storefront')
(r/'components/listing.tsx').write_text('''"use client";
import Link from 'next/link';
import {useRouter,useSearchParams} from 'next/navigation';
import {ArrowRight,SlidersHorizontal,X} from 'lucide-react';
import {Catalog,Product,slugify} from '@/lib/store';
import {ProductCard} from './store';
export default function Listing({data,products,title,description}:{data:Catalog;products:Product[];title:string;description:string}){const router=useRouter();const params=useSearchParams();const update=(key:string,value:string)=>{const query=new URLSearchParams(params.toString());if(value)query.set(key,value);else query.delete(key);query.delete('page');router.push('?'+query.toString());};return <main id="main" className="container catalog-page"><div className="breadcrumbs"><Link href="/">Home</Link><span>/</span><span>{title}</span></div><div className="catalog-heading"><span className="eyebrow">THOUGHTFULLY CHOSEN FOR YOUR HOME</span><h1>{title}</h1><p>{description}</p></div><div className="catalog-layout"><aside className="catalog-filters"><h3><SlidersHorizontal size={17}/>Refine your search</h3><label>Brand<select value={params.get('brand')||''} onChange={event=>update('brand',event.target.value)}><option value="">All brands</option>{data.brands.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select></label><label>Category<select value={params.get('category')||''} onChange={event=>update('category',event.target.value)}><option value="">All categories</option>{data.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><div className="price-filter"><label>Minimum price<input type="number" min="0" defaultValue={params.get('min')||''} placeholder="KSh 0" onBlur={event=>update('min',event.target.value)}/></label><label>Maximum price<input type="number" min="0" defaultValue={params.get('max')||''} placeholder="Any price" onBlur={event=>update('max',event.target.value)}/></label></div><label>Specification<input value={params.get('spec')||''} placeholder="e.g. 8 kg, Silver" onChange={event=>update('spec',event.target.value)}/></label><label className="check-label"><input type="checkbox" checked={params.get('available')==='1'} onChange={event=>update('available',event.target.checked?'1':'')}/>In stock only</label><label className="check-label"><input type="checkbox" checked={params.get('sale')==='1'} onChange={event=>update('sale',event.target.checked?'1':'')}/>Special offers only</label><Link href="?" className="clear-filters"><X size={14}/>Clear filters</Link><div className="filter-help"><h3>A little help choosing?</h3><p>Our team can help you find the right fit.</p><Link href="/contact">Get in touch <ArrowRight size={15}/></Link></div></aside><section><div className="catalog-toolbar"><span>{products.length} products {params.get('q')?`for "${params.get('q')}"`:''}</span><label>Sort by <select value={params.get('sort')||'featured'} onChange={event=>update('sort',event.target.value)}><option value="featured">Featured</option><option value="newest">Newest arrivals</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name A-Z</option></select></label></div><div className="product-grid catalog-products">{products.slice((Math.max(1,Number(params.get('page'))||1)-1)*12,Math.max(1,Number(params.get('page'))||1)*12).map(p=><ProductCard product={p} key={p.id}/>)}</div>{!products.length&&<div className="empty-state"><h2>No products match your search.</h2><p>Try a different category or clear your filters.</p><Link className="button" href="?">Reset filters</Link></div>}{products.length>12&&<div className="pagination">{Array.from({length:Math.ceil(products.length/12)},(_,index)=><Link key={index} className={Number(params.get('page')||1)===index+1?'selected':''} href={'?'+new URLSearchParams({...Object.fromEntries(params),page:String(index+1)})}>{index+1}</Link>)}</div>}</section></div></main>}
''')
(r/'lib/filter.ts').write_text('''import {Product,price} from './store';
export function filter(products:Product[],query:Record<string,string|undefined>){let result=products.filter(p=>(!query.q||`${p.name} ${p.sku}`.toLowerCase().includes(query.q.toLowerCase()))&&(!query.brand||p.brand_id===query.brand)&&(!query.category||p.category_ids?.includes(query.category))&&(!query.min||price(p)>=Number(query.min))&&(!query.max||price(p)<=Number(query.max))&&(!query.spec||(p.specifications||'').toLowerCase().includes(query.spec.toLowerCase()))&&(query.available!=='1'||p.type==='Simple'&&p.stock-(p.reserved||0)>0)&&(query.sale!=='1'||p.sale_price!=null&&p.sale_price<p.price));if(query.sort==='price-low')result.sort((a,b)=>price(a)-price(b));if(query.sort==='price-high')result.sort((a,b)=>price(b)-price(a));if(query.sort==='newest')result.sort((a,b)=>b.created_at.localeCompare(a.created_at));if(query.sort==='name')result.sort((a,b)=>a.name.localeCompare(b.name));return result;}
''')
(r/'app/products/page.tsx').write_text('''import {catalog} from '@/lib/store';import {filter} from '@/lib/filter';import Listing from '@/components/listing';
export const metadata={title:'Shop all products'};
export default async function Products({searchParams}:{searchParams:Promise<Record<string,string>>}){const data=await catalog();const query=await searchParams;return <Listing data={data} products={filter(data.products,query)} title="Your everyday, upgraded." description="Find hardworking appliances from the brands you love. A good fit for every room and every routine."/>}
''')
(r/'app/categories/[slug]/page.tsx').write_text('''import {notFound} from 'next/navigation';import {catalog} from '@/lib/store';import {filter} from '@/lib/filter';import Listing from '@/components/listing';
export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const data=await catalog();return {title:data.categories.find(c=>c.slug===(await params).slug)?.name||'Category'}}
export default async function Category({params,searchParams}:{params:Promise<{slug:string}>;searchParams:Promise<Record<string,string>>}){const data=await catalog();const {slug}=await params;const category=data.categories.find(c=>c.slug===slug);if(!category)notFound();return <Listing data={data} products={filter(data.products.filter(p=>p.category_ids?.includes(category.id)),await searchParams)} title={category.name} description={category.description||'Thoughtful finds for a better everyday.'}/>}
''')
# Fix asynchronous params before array predicates.
p=r/'app/categories/[slug]/page.tsx';s=p.read_text().replace("const data=await catalog();return {title:data.categories.find(c=>c.slug===(await params).slug)?.name||'Category'}", "const data=await catalog();const {slug}=await params;return {title:data.categories.find(c=>c.slug===slug)?.name||'Category'}");p.write_text(s)
(r/'app/brands/[slug]/page.tsx').write_text('''import {notFound} from 'next/navigation';import {catalog,slugify} from '@/lib/store';import {filter} from '@/lib/filter';import Listing from '@/components/listing';
export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const data=await catalog();const {slug}=await params;return {title:data.brands.find(b=>slugify(b.name)===slug)?.name||'Brand'}}
export default async function Brand({params,searchParams}:{params:Promise<{slug:string}>;searchParams:Promise<Record<string,string>>}){const data=await catalog();const {slug}=await params;const brand=data.brands.find(b=>slugify(b.name)===slug);if(!brand)notFound();return <><section className={'brand-banner '+slugify(brand.name)}><div className="container"><span className="eyebrow">THE BRANDS YOU KNOW. THE QUALITY YOU LOVE.</span><h1>{brand.name}</h1><p>{brand.description}</p>{brand.banner&&<img src={brand.banner} alt={brand.name}/>}</div></section><Listing data={data} products={filter(data.products.filter(p=>p.brand_id===brand.id),await searchParams)} title={brand.name+' collection'} description="Explore the full collection and find the right fit for your home."/></>}
''')
(r/'components/product-detail.tsx').write_text('''"use client";
import {useEffect,useRef,useState} from 'react';import Link from 'next/link';import Image from 'next/image';import {ShoppingBag,Minus,Plus,Heart,X,Star,FileDown,MessageCircle,ShieldCheck,Truck} from 'lucide-react';import {Product,money,price,storeRequest} from '@/lib/store';import {useStore,ProductImage} from './store';
export function Gallery({product}:{product:Product}){const images=[product.image,...(product.gallery_images||[])].filter(Boolean) as string[];const [selected,setSelected]=useState(0),[zoom,setZoom]=useState(false);useEffect(()=>{if(!zoom)return;const previous=document.body.style.overflow;document.body.style.overflow='hidden';const handler=(event:KeyboardEvent)=>{if(event.key==='Escape')setZoom(false);};window.addEventListener('keydown',handler);return()=>{document.body.style.overflow=previous;window.removeEventListener('keydown',handler);};},[zoom]);return <div className="product-gallery-panel"><button className="main-product-photo" aria-label="Zoom product image" onClick={()=>setZoom(true)}>{images.length?<Image src={images[selected]} alt={product.name} width={700} height={700} priority unoptimized={images[selected].endsWith('.svg')}/>:<ProductImage product={product}/>}<span>Click to take a closer look</span></button><div className="product-thumbnails">{images.map((image,index)=><button key={index} aria-label={'View product image '+(index+1)} className={selected===index?'selected':''} onClick={()=>setSelected(index)}><Image src={image} alt="" width={90} height={90} unoptimized={image.endsWith('.svg')}/></button>)}</div>{zoom&&<div className="photo-zoom" role="dialog" aria-modal="true" aria-label="Product image" onClick={()=>setZoom(false)}><button aria-label="Close image" autoFocus onClick={()=>setZoom(false)}><X size={27}/></button>{images.length&&<img src={images[selected]} alt={product.name}/>}</div>}</div>}
export function ProductActions({product}:{product:Product}){const {add,wishlist,favorite,data}=useStore();const [quantity,setQuantity]=useState(1);const available=product.type==='Simple'?Math.max(0,product.stock-(product.reserved||0)):0;const whatsapp=(data.settings.whatsapp||data.settings.phone||'').replace(/[^0-9]/g,'');return <><div className="detail-price"><strong>{money(price(product))}</strong>{product.sale_price!=null&&product.sale_price<product.price&&<del>{money(product.price)}</del>}</div><span className={'availability '+(available?'in-stock':'out-stock')}><i/>{available?'Available to order':'Currently unavailable'}</span><div className="purchase-actions"><div className="quantity"><button aria-label="Decrease quantity" onClick={()=>setQuantity(Math.max(1,quantity-1))}><Minus size={15}/></button><span>{quantity}</span><button aria-label="Increase quantity" disabled={quantity>=available} onClick={()=>setQuantity(quantity+1)}><Plus size={15}/></button></div><button className="button" disabled={!available} onClick={()=>add(product,quantity)}><ShoppingBag size={18}/>Add to bag</button><button className={'wishlist-detail '+(wishlist.includes(product.id)?'selected':'')} aria-label="Toggle wishlist" onClick={()=>favorite(product.id)}><Heart fill={wishlist.includes(product.id)?'currentColor':'none'}/></button></div><div className="detail-assurances"><span><Truck size={18}/>Delivery rate calculated at checkout</span><span><ShieldCheck size={18}/>{product.warranty||'Ask our team about warranty coverage'}</span></div>{product.manual&&<a className="detail-link" href={product.manual} target="_blank" rel="noreferrer"><FileDown size={17}/>Download manual / brochure</a>}{whatsapp&&<a className="detail-link" href={'https://wa.me/'+whatsapp+'?text='+encodeURIComponent('Hello, I would like to know more about '+product.name)} target="_blank" rel="noreferrer"><MessageCircle size={17}/>Ask about this product</a>}</>}
export function Reviews({productId}:{productId:string}){const {account}=useStore();const [reviews,setReviews]=useState<any[]>([]),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const submission=useRef('');useEffect(()=>{storeRequest('product-reviews/'+productId).then(result=>setReviews(result.data)).catch(error=>setMessage(error.message));},[productId]);return <section className="product-reviews"><div className="section-heading"><div><span className="eyebrow">FROM HOMES LIKE YOURS</span><h2>Customer reviews</h2></div><span>{reviews.length} approved reviews</span></div><div className="reviews-layout"><div>{reviews.map(review=><article className="review-card" key={review.id}><div className="review-stars">{[1,2,3,4,5].map(value=><Star key={value} size={14} fill={value<=review.rating?'currentColor':'none'}/>)}</div><h3>{review.title||'Customer review'}</h3><p>{review.body}</p><small>{review.customer_name} / {new Date(review.created_at).toLocaleDateString('en-KE')}</small></article>)}{!reviews.length&&<p className="muted">No published reviews yet. Share your experience with this product.</p>}</div><form className="review-form" onSubmit={async event=>{event.preventDefault();if(busy)return;setBusy(true);setMessage('');const form=event.currentTarget;const input=Object.fromEntries(new FormData(form));submission.current||=crypto.randomUUID();try{const result=await storeRequest('reviews','POST',{...input,rating:Number(input.rating),product_id:productId,submission_id:submission.current});setMessage(result.message);form.reset();submission.current='';}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}><h3>Tell us what you think</h3>{account?<><label>Rating<select name="rating" defaultValue="5">{[5,4,3,2,1].map(value=><option value={value} key={value}>{value} stars</option>)}</select></label><label>Review title<input name="title" maxLength={180}/></label><label>Your review<textarea name="body" required maxLength={5000} rows={4}/></label><button className="button" disabled={busy}>{busy?'Submitting...':'Submit review'}</button><small>Reviews are checked before publication.</small></>:<p><Link href="/account">Sign in</Link> to share your experience.</p>}{message&&<p role="status" className="form-feedback">{message}</p>}</form></div></section>}
''')
(r/'app/products/[slug]/page.tsx').write_text('''import Link from 'next/link';import {notFound} from 'next/navigation';import {catalog,slugify} from '@/lib/store';import {Gallery,ProductActions,Reviews} from '@/components/product-detail';import {ProductCard} from '@/components/store';
export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const data=await catalog();const {slug}=await params;const p=data.products.find(p=>p.slug===slug);return {title:p?.seo_title||p?.name||'Product',description:p?.seo_description||p?.description}}
export default async function ProductPage({params}:{params:Promise<{slug:string}>}){const data=await catalog();const {slug}=await params;const product=data.products.find(p=>p.slug===slug);if(!product)notFound();const brand=data.brands.find(b=>b.id===product.brand_id);const specs=(product.specifications||'').split(/\\n|\\\\n/).filter(Boolean).map(line=>{const colon=line.indexOf(':');return colon>=0?[line.slice(0,colon),line.slice(colon+1)]:['Specification',line]});return <main id="main" className="container product-detail-page"><div className="breadcrumbs"><Link href="/">Home</Link><span>/</span><Link href="/products">Shop</Link><span>/</span><span>{product.name}</span></div><div className="product-detail-grid"><Gallery product={product}/><section className="product-detail-copy">{brand&&<Link className="eyebrow" href={'/brands/'+slugify(brand.name)}>{brand.name}</Link>}<h1>{product.name}</h1><span className="product-sku">SKU: {product.sku}</span><p>{product.description}</p><ProductActions product={product}/></section></div><div className="product-information"><section><span className="eyebrow">A CLOSER LOOK</span><h2>Made to make life easier.</h2><p className="preserve-lines">{product.description}</p>{product.warranty&&<p><strong>Warranty:</strong> {product.warranty}</p>}</section><section><h2>Specifications</h2>{specs.length?<table><tbody>{specs.map(([key,value],i)=><tr key={i}><th>{key}</th><td>{value}</td></tr>)}</tbody></table>:<p>Contact our team for detailed specifications.</p>}</section></div><Reviews productId={product.id}/><section className="section"><div className="section-heading"><div><span className="eyebrow">A FEW MORE THOUGHTFUL FINDS</span><h2>You might also like.</h2></div></div><div className="product-grid">{data.products.filter(p=>p.id!==product.id&&(p.brand_id===product.brand_id||p.category_ids?.some(id=>product.category_ids?.includes(id)))).slice(0,4).map(p=><ProductCard key={p.id} product={p}/>)}</div></section></main>}
''')
